<?php
require_once __DIR__.'/../config/bootstrap.php';$pageTitle='Fretes';$rows=$pdo->query("SELECT f.*,c.name carrier,o.city origin_city,d.city destination_city,(SELECT COUNT(*) FROM freight_products fp WHERE fp.freight_id=f.id) product_count FROM freights f JOIN carriers c ON c.id=f.carrier_id JOIN addresses o ON o.id=f.origin_id JOIN addresses d ON d.id=f.destination_id ORDER BY f.freight_date DESC,f.id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><span class="eyebrow">OPERAÇÕES</span><h1>Fretes</h1><p>Consulte e gerencie suas operações de transporte.</p></div><a class="btn btn-primary" href="<?=e(url('freights/create.php'))?>">＋ Gerar frete</a></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Código</th><th>Data</th><th>Transportador</th><th>Trajeto</th><th>Produtos</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong>#<?= (int)$r['id']?></strong></td><td><?=e(date('d/m/Y',strtotime($r['freight_date'])))?></td><td><?=e($r['carrier'])?></td><td><?=e($r['origin_city'])?> → <?=e($r['destination_city'])?></td><td><?= (int)$r['product_count']?></td><td><span class="status"><?=e($r['status'])?></span></td><td><a class="table-action" href="<?=e(url('freights/show.php?id='.$r['id']))?>">Detalhes</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">Nenhum frete cadastrado.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
